import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

export function openProjectStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    )
  `);
  const list = database.prepare('SELECT id, name FROM projects ORDER BY id');
  const find = database.prepare('SELECT id, name FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');

  return {
    list: () => list.all(),
    find: (id) => find.get(id),
    create(name) {
      const trimmedName = name.trim();
      if (!trimmedName) throw new Error('Project name is required');
      return insert.run(trimmedName).lastInsertRowid;
    },
    close: () => database.close(),
  };
}
import { createServer } from 'node:http';
import { openProjectStore } from './database.js';
import { notFoundPage, projectListPage, projectPage } from './pages.js';

const store = openProjectStore(process.env.DB_PATH || 'data/workboard.sqlite');

function html(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let bytes = 0;
  for await (const chunk of request) {
    bytes += chunk.length;
    if (bytes > 65536) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const { pathname } = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && pathname === '/') {
      html(response, 200, projectListPage(store.list()));
    } else if (request.method === 'POST' && pathname === '/projects') {
      const form = await readForm(request);
      const name = form.get('name') || '';
      if (!name.trim()) {
        html(response, 422, projectListPage(store.list(), 'Project name is required', name));
        return;
      }
      store.create(name);
      response.writeHead(303, { Location: '/' });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/[1-9]\d*$/.test(pathname)) {
      const id = Number(pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
      html(response, project ? 200 : 404, project ? projectPage(project) : notFoundPage());
    } else {
      html(response, 404, notFoundPage());
    }
  } catch (error) {
    if (!error.status) console.error(error);
    response.writeHead(error.status || 500, { 'Content-Type': 'text/plain; charset=utf-8' });
    response.end(error.status ? error.message : 'Internal server error');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    store.close();
  });
}

process.once('SIGINT', shutdown);
process.once('SIGTERM', shutdown);
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(title)} | Workboard</title>
    <style>
      * { box-sizing: border-box; }
      body { margin: 0; background: #f5f7fa; color: #182332; font: 1rem/1.5 system-ui, sans-serif; }
      main { max-width: 760px; margin: 3rem auto; padding: 0 1.25rem; }
      h1 { overflow-wrap: anywhere; }
      label { display: block; font-weight: 600; margin-bottom: .4rem; }
      input { width: 100%; padding: .7rem; border: 1px solid #66758a; border-radius: .35rem; font: inherit; }
      button { padding: .65rem 1rem; border: 1px solid #2354a0; border-radius: .35rem; background: #2354a0; color: white; font: inherit; cursor: pointer; }
      button:focus-visible, input:focus-visible { outline: 3px solid #bd6a00; outline-offset: 3px; }
      .create button { margin-top: .8rem; }
      .projects { list-style: none; padding: 0; }
      .project { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-top: .75rem; padding: 1rem; background: white; border: 1px solid #cbd3dd; border-radius: .5rem; }
      .project span { overflow-wrap: anywhere; min-width: 0; }
      .project form { flex-shrink: 0; }
      [role="alert"] { color: #9a1b1b; font-weight: 600; }
      @media (max-width: 480px) { .project { align-items: flex-start; flex-direction: column; } }
    </style>
  </head>
  <body><main>${content}</main></body>
</html>`;
}

export function projectListPage(projects, error = '', name = '') {
  return page('Projects', `
    <h1>Workboard</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" method="post" action="/projects">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" value="${escapeHtml(name)}">
      <button type="submit">Create project</button>
    </form>
    <ul class="projects" aria-label="Projects">
      ${projects.map((project) => `<li class="project" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
      </li>`).join('')}
    </ul>
  `);
}

export function projectPage(project) {
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    <form method="get" action="/"><button type="submit">Projects</button></form>`);
}

export function notFoundPage() {
  return page('Page not found', '<h1>Page not found</h1><a href="/">Projects</a>');
}
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const url = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`Server exited (${code}): ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    url,
    async stop() {
      if (child.exitCode !== null || child.signalCode !== null) return;
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('projects validate, preserve names and IDs, and survive a server restart', async (t) => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'projects.sqlite');
  let server;
  t.after(async () => {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  });
  server = await startServer(databasePath);
  const get = (path) => fetch(`${server.url}${path}`);
  const create = (name) => fetch(`${server.url}/projects`, {
    method: 'POST',
    body: new URLSearchParams({ name }),
    redirect: 'manual',
  });

  const health = await get('/health');
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: 'ok' });
  const initial = await (await get('/')).text();
  assert.match(initial, /<h1>Workboard<\/h1>/);
  assert.match(initial, /<label for="project-name">Project name<\/label>/);
  assert.match(initial, />Create project<\/button>/);
  assert.doesNotMatch(initial, /data-testid="project-row"/);

  for (const name of ['', '  \t\n ']) {
    const invalid = await create(name);
    assert.equal(invalid.status, 422);
    const body = await invalid.text();
    assert.match(body, /role="alert">Project name is required/);
    assert.doesNotMatch(body, /data-testid="project-row"/);
  }

  const created = await create('  First project  ');
  assert.equal(created.status, 303);
  assert.equal(created.headers.get('location'), '/');
  await created.text();
  const second = await create('<script>alert("x")</script> & next');
  assert.equal(second.status, 303);
  await second.text();

  const list = await (await get('/')).text();
  assert.equal([...list.matchAll(/data-testid="project-row"/g)].length, 2);
  assert.match(list, /<span>First project<\/span>/);
  assert.match(list, /&lt;script&gt;alert\(&quot;x&quot;\)&lt;\/script&gt; &amp; next/);
  assert.doesNotMatch(list, /<script>/);
  const paths = [...list.matchAll(/action="(\/projects\/\d+)"/g)].map((match) => match[1]);
  assert.equal(paths.length, 2);
  assert.notEqual(paths[0], paths[1]);
  assert.ok(list.indexOf('First project') < list.indexOf('&lt;script&gt;'));
  const detail = await (await get(paths[0])).text();
  assert.match(detail, /<h1>First project<\/h1>/);
  assert.match(detail, /action="\/".*>Projects<\/button>/);
  assert.equal((await get('/projects/999999')).status, 404);
  assert.equal((await get('/projects/9007199254740993')).status, 404);

  const invalidAfterCreation = await create('   ');
  assert.equal(invalidAfterCreation.status, 422);
  assert.match(await invalidAfterCreation.text(), /role="alert">Project name is required/);
  assert.equal(await (await get('/')).text(), list);
  await server.stop();
  server = await startServer(databasePath);
  assert.equal(await (await get('/')).text(), list);
  assert.equal(await (await get(paths[0])).text(), detail);
});
# Workboard

Requires Node.js 22.22.1. No application dependencies or installation step are needed.

Run `npm start` to serve on `0.0.0.0:8080`. Set `PORT` to change the port and
`DB_PATH` to choose the persistent SQLite file (default: `data/workboard.sqlite`).
The parent database directory is created on startup. `GET /health` returns
`{"status":"ok"}`. Stop with SIGINT or SIGTERM to close the server and database.

Run `npm test` for integration checks using temporary databases, including
validation, project navigation, and persistence across server restarts.
